var res = [];

function push(title, url, num, g, action) {
  var j = { title: title, url: url, style: { layout_flexBasisPercent: num, layout_flexGrow: (g == 0 ? 0 : 1) } };
  if (action) {
    j.action = action.action;
    j.name = action.name || title;
    j.type = action.type;
    j.chars = action.chars;
    j.viewName = action.viewName;
    j.default = action.default;
  }
  res.push(j);
}

function go(m) { return "lvSetMenu('" + m + "')"; }

var d = {};
try { d = JSON.parse(String(source.getVariable() || '{}')); } catch (e) {}
var menu = String(d.menu || 'main');
var mode = String(d.mode || '小说');
if (mode !== '小说' && mode !== '听书' && mode !== '短剧') mode = '小说';
var audioOn = (d.audioPlay !== false);

if (menu === 'mode') {
  push('选择模式', '', 1, 0, { type: 'button' });
  push('📖 小说', '', 0.45, 1, { type: 'button', action: "lvSetMode('小说')" });
  push('🎧 听书', '', 0.45, 1, { type: 'button', action: "lvSetMode('听书')" });
  push('🎬 短剧', '', 0.45, 1, { type: 'button', action: "lvSetMode('短剧')" });
  push('← 返回', '', 0.45, 1, { type: 'button', action: go('main') });
} else if (menu === 'func') {
  push('功能设置', '', 1, 0, { type: 'button' });
  push('💬 段评气泡：' + (d.showPara ? '开' : '关'), '', 1, 1, { type: 'button', action: 'lvTogglePara()' });
  push('🔊 听书播放：' + (audioOn ? '开' : '关'), '', 1, 1, { type: 'button', action: 'lvToggleAudio()' });
  push('📝 章末摘要：' + (d.summary ? '开' : '关'), '', 1, 1, { type: 'button', action: 'lvSummary()' });
  push('← 返回', '', 1, 1, { type: 'button', action: go('main') });
} else if (menu === 'sys') {
  push('系统', '', 1, 0, { type: 'button' });
  push('🔌 接口测试', '', 0.45, 1, { type: 'button', action: 'lvTest()' });
  push('📊 状态', '', 0.45, 1, { type: 'button', action: 'lvStatus()' });
  push('🔄 恢复默认', '', 0.45, 1, { type: 'button', action: 'lvBegin()' });
  push('🧹 清空设置', '', 0.45, 1, { type: 'button', action: 'lvClean()' });
  push('← 返回', '', 0.45, 1, { type: 'button', action: go('main') });
} else {
  push('🍅 番茄小说TS', '', 1, 0, { type: 'button' });
  push('🔀 ' + mode, '', 0.45, 1, { type: 'button', action: go('mode') });
  push('⚙️ 功能设置', '', 0.45, 1, { type: 'button', action: go('func') });
  push('🛠️ 系统', '', 0.45, 1, { type: 'button', action: go('sys') });
  push('ℹ️ 关于', '', 0.45, 1, { type: 'button', action: 'lvAbout()' });
}

JSON.stringify(res);

