@js:
(function(){
var out='';
try{ out=String(java.getString('.con@all')||''); }catch(e){}
try{
  var h=String(result||'');
  var m=h.match(/<script[^>]+src\s*=\s*["']([^"']*a\.aspx[^"']*)["']/i);
  if(m){
    var u=String(m[1]);
    if(u.indexOf('http')!==0){
      try{ u=String(java.getAbsoluteURL(u)); }catch(e){ if(u.charAt(0)==='/'){ u='https://www.suduguu.com'+u; } }
    }
    var r=String(java.ajax(u)||'');
    var w=r.match(/document\.write\(\s*"([\s\S]*)"\s*\)/);
    if(w){ out=out+String(w[1]).replace(/\\(["\\\/])/g,'$1'); }
  }
}catch(e){}
return out;
})()
